import{_ as e,c as t,aU as o,a as r}from"./chunks/framework.DIXiA2XH.js";const u=JSON.parse('{"title":"分布式","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/mianshi/分布式.md","filePath":"note/back-end/mianshi/分布式.md","lastUpdated":1775662537000}'),l={name:"note/back-end/mianshi/分布式.md"};function i(n,a,s,d,h,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="分布式" tabindex="-1">分布式 <a class="header-anchor" href="#分布式" aria-label="Permalink to &quot;分布式&quot;">​</a></h1><h2 id="cap" tabindex="-1">CAP <a class="header-anchor" href="#cap" aria-label="Permalink to &quot;CAP&quot;">​</a></h2><p>分区容错性 是指分布式网络中部分网络不可用，但系统依然正常对外提供服务。</p><p>比如：北京的订单系统，访问上海的库存系统，可能导致失败。如果发生失败，就要在A和C之间做出选择。 要么停止系统进行错误恢复，要么继续服务但是降低一致性，所以说只能保证AP或CP。</p><p>所以，只要是分布式系统，因为网络故障是百分百存在的，所以P是必备的，剩下的就是AP还是CP了</p><h2 id="如何保证幂等" tabindex="-1">如何保证幂等 <a class="header-anchor" href="#如何保证幂等" aria-label="Permalink to &quot;如何保证幂等&quot;">​</a></h2><p>所谓幂等，其实就是说你这个操作，执行1次和多次返回的结果是一样的。</p><ol><li>用数据库唯一键实现</li><li>业务实现，执行前先查询是否存在或者状态字段来判断是否已经处理过了</li><li>颁发token，再加分布式锁，处理完之后删除token，下一个同样的请求就被拦截住了</li></ol><h2 id="分布式锁" tabindex="-1">分布式锁 <a class="header-anchor" href="#分布式锁" aria-label="Permalink to &quot;分布式锁&quot;">​</a></h2><p><strong>什么是分布式锁？</strong></p><p>在分布式环境下，多个线程需要操作同一份资源，只允许一个线程进行操作。</p><h3 id="数据库实现" tabindex="-1">数据库实现 <a class="header-anchor" href="#数据库实现" aria-label="Permalink to &quot;数据库实现&quot;">​</a></h3><p>可以基于数据库，新增一条数据，uk唯一键来实现，或者根据<code>for update</code>来实现，都可以。</p><blockquote><p>前提肯定是需要根据业务有一个唯一的key，也就是锁，然后新增成功就说明获取锁成功，业务执行完成之后就删掉即可。</p></blockquote><h3 id="redis实现" tabindex="-1">redis实现 <a class="header-anchor" href="#redis实现" aria-label="Permalink to &quot;redis实现&quot;">​</a></h3><p><code>setnx()</code>来实现， <code>setnx(lockkey, 当前时间+过期超时时间)，如果返回 1，则获取锁成功；如果返回 0 则没有获取到锁。</code></p><h2 id="服务降级和熔断" tabindex="-1">服务降级和熔断 <a class="header-anchor" href="#服务降级和熔断" aria-label="Permalink to &quot;服务降级和熔断&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">注意，实际场景中熔断和降级貌似是一体的，触发接口的异常阈值，则走callback方法，如果想单独走降级的话，则可以采用配置中心的方法来实现。</p><p></p><p>如果熔断器没有配置callback,则会直接抛出<code>HystrixTimeoutException</code>异常</p></div><ul><li>服务熔断：主动切断故障服务的调用，防止雪崩，保护调用方。是一种故障检测和恢复机制。</li><li>服务降级：主动关闭非核心服务，释放资源，保障核心业务。是一种资源调配和保稳策略。 举例说明：</li></ul><p><strong>场景</strong>：一个电商网站，其下单功能依赖于“库存服务”和“推荐服务”。</p><ol><li><p><strong>服务熔断的例子</strong>：</p><ul><li><strong>库存服务</strong>突然响应极慢或大量超时。</li><li><strong>熔断器</strong>会快速检测到这种故障，<strong>立即“跳闸”</strong>。</li><li>后续所有对库存服务的调用都会被直接拒绝或返回一个预设的降级值（如“库存检查中”），而不再真正发起请求。</li><li><strong>目的</strong>：防止大量请求线程被挂起，导致订单服务本身也因资源耗尽而崩溃。</li></ul></li><li><p><strong>服务降级的例子</strong>：</p><ul><li>在“双十一”大促期间，系统流量激增，为了保证核心的<strong>下单、支付</strong>流程能正常运行。</li><li>系统<strong>主动关闭</strong>了“推荐服务”（比如“猜你喜欢”）这类非核心但耗资源的功能，显示一个简单的静态页面。</li><li><strong>目的</strong>：将节省下来的CPU、内存、数据库连接等资源，全部让给核心交易链路，保证整体系统不宕机。</li></ul></li></ol><p><strong>总结</strong>：熔断是 <strong>“因为它坏了，所以我不用它”</strong> ；降级是 <strong>“虽然它没坏，但为了大局，我先不用它”</strong> 。</p><h2 id="限流" tabindex="-1">限流 <a class="header-anchor" href="#限流" aria-label="Permalink to &quot;限流&quot;">​</a></h2><h3 id="redis实现-1" tabindex="-1">redis实现 <a class="header-anchor" href="#redis实现-1" aria-label="Permalink to &quot;redis实现&quot;">​</a></h3><p>利用redis的计数器，原理是，给这个秒杀接口url （作为key）初始化值1，如果是第一次的话，就给这个key设置过期时间60s， 我们限制秒杀接口一分钟最多1w个请求。没来一次请求就加一，超过1w就返回 人数较多，请稍后再试。还可以限制ip，用户，等等条件。无非是key改变下就可以了</p><h3 id="滑动窗口限流" tabindex="-1">滑动窗口限流 <a class="header-anchor" href="#滑动窗口限流" aria-label="Permalink to &quot;滑动窗口限流&quot;">​</a></h3><p>可以自己用java实现，也很简单</p><h2 id="第三方组件" tabindex="-1">第三方组件 <a class="header-anchor" href="#第三方组件" aria-label="Permalink to &quot;第三方组件&quot;">​</a></h2><p>alibaba-sentinel 限流组件。非常简单好用而且强大</p><h2 id="秒杀场景" tabindex="-1">秒杀场景 <a class="header-anchor" href="#秒杀场景" aria-label="Permalink to &quot;秒杀场景&quot;">​</a></h2><ul><li>前端：页面静态化，cdn，验证码，防抖。</li><li>后端：限流，redis+lua脚本实现高性能秒杀</li></ul>',31)])])}const b=e(l,[["render",i]]);export{u as __pageData,b as default};
